<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,HttpException,RuntimeContext};

final class EvidenceRetentionService
{
    use TenantOperations;
    private const CATEGORIES=[
        'gate_records'=>['gate_register','gate_id','occurred_at','DELETE'],
        'report_photos'=>['report_photos','photo_id','created_at','DELETE'],
        'location_history'=>['gps_locations','gps_location_id','captured_at','DELETE'],
        'location_events'=>['gps_events','gps_event_id','occurred_at','DELETE'],
        'incident_evidence'=>['incident_evidence','evidence_id','received_at','REMOVE_FILE'],
        'visitor_profiles'=>['visitors','visitor_id','updated_at','REDACT_PROFILE'],
    ];
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit) {}
    private function category(mixed $value): string {if(!is_string($value)||!isset(self::CATEGORIES[$value]))throw HttpException::unprocessable('Unsupported retention category.');return $value;}
    private function mfa(): void {if(!$this->context->mfaVerified())throw HttpException::forbidden('Use an MFA-authenticated session for retention management.');}
    public function evidenceList(array $input): array {
        $this->fields($input,['incident_id']);$incident=$this->row('incidents','incident_id',$input['incident_id']??null);$this->audit->record('incident_evidence','metadata_viewed',(string)$incident['incident_id']);return $this->db->fetchAll('SELECT evidence_id,incident_id,original_filename,byte_length,sha256,description,captured_at,received_at,created_by_user_id,supersedes_evidence_id,purged_at FROM incident_evidence WHERE company_id=:company AND incident_id=:incident ORDER BY evidence_id LIMIT 200',['company'=>$this->company(),'incident'=>$incident['incident_id']]);
    }
    public function addEvidence(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['incident_id','original_filename','file_base64','description','captured_at','supersedes_evidence_id']);$incident=$this->row('incidents','incident_id',$input['incident_id']??null);if(!empty($incident['deleted_at']))throw HttpException::notFound();$filename=$this->text($input['original_filename']??null,150);if(preg_match('/[\\\\\/\x00-\x1f\x7f]/',$filename))throw HttpException::unprocessable('Use a filename without directories or control characters.');
        $encoded=$input['file_base64']??null;if(!is_string($encoded)||strlen($encoded)>350000)throw HttpException::unprocessable('Evidence must be a base64 file of at most 256 KiB.');$bytes=base64_decode($encoded,true);if($bytes===false||strlen($bytes)===0||strlen($bytes)>262144)throw HttpException::unprocessable('Invalid evidence file or size.');$at=$this->at($input['captured_at']??null);if(strtotime($at.' UTC')>time()+300)throw HttpException::unprocessable('Capture time cannot be in the future.');
        $prior=empty($input['supersedes_evidence_id'])?null:$this->row('incident_evidence','evidence_id',$input['supersedes_evidence_id']);if($prior&&(string)$prior['incident_id']!==(string)$incident['incident_id'])throw HttpException::unprocessable('A correction must reference evidence for the same incident.');
        $this->db->execute('INSERT INTO incident_evidence(company_id,incident_id,original_filename,file_base64,byte_length,sha256,description,captured_at,received_at,created_by_user_id,supersedes_evidence_id) VALUES(:company,:incident,:filename,:file,:bytes,:hash,:description,:captured,:received,:actor,:prior)',['company'=>$this->company(),'incident'=>$incident['incident_id'],'filename'=>$filename,'file'=>base64_encode($bytes),'bytes'=>strlen($bytes),'hash'=>hash('sha256',$bytes),'description'=>$this->text($input['description']??null,1000),'captured'=>$at,'received'=>gmdate('Y-m-d H:i:s'),'actor'=>$this->actor(),'prior'=>$prior['evidence_id']??null]);return $this->created('incident_evidence')+['sha256'=>hash('sha256',$bytes),'bytes'=>strlen($bytes)];
    });}
    private function access(array $row,string $action): void {
        $this->db->execute('INSERT INTO evidence_access_history(company_id,evidence_id,actor_user_id,action_name,reason,occurred_at,sha256) VALUES(:company,:evidence,:actor,:action,:reason,:now,:hash)',['company'=>$this->company(),'evidence'=>$row['evidence_id'],'actor'=>$this->actor(),'action'=>$action,'reason'=>'Authenticated investigation review','now'=>gmdate('Y-m-d H:i:s'),'hash'=>$row['sha256']]);$this->audit->record('incident_evidence',$action,(string)$row['evidence_id']);
    }
    private function checkedBytes(array $row): string|false {
        $bytes=base64_decode($row['file_base64'],true);return $bytes!==false&&strlen($bytes)===(int)$row['byte_length']&&hash_equals($row['sha256'],hash('sha256',$bytes))?$bytes:false;
    }
    /** GET route: commit the failure receipt before reporting an integrity error. */
    public function download(string $id): array {
        $result=$this->atomic(function()use($id){$row=$this->row('incident_evidence','evidence_id',$id);if($row['purged_at']!==null)throw HttpException::notFound('Original file has been removed by retention.');$bytes=$this->checkedBytes($row);$this->access($row,$bytes===false?'integrity_failed':'downloaded');return ['bytes'=>$bytes,'sha256'=>$row['sha256']];});if($result['bytes']===false)throw HttpException::conflict('Stored evidence failed its integrity check.');return $result;
    }
    public function history(string $id): array {$this->row('incident_evidence','evidence_id',$id);return $this->db->fetchAll('SELECT action_name,actor_user_id,reason,occurred_at,sha256 FROM evidence_access_history WHERE company_id=:company AND evidence_id=:id ORDER BY access_id',['company'=>$this->company(),'id'=>$id]);}
    public function investigationPack(string $id): array {
        $result=$this->atomic(function()use($id){$incident=$this->row('incidents','incident_id',$id);$records=$this->db->fetchAll('SELECT * FROM incident_evidence WHERE company_id=:company AND incident_id=:id ORDER BY evidence_id LIMIT 51',['company'=>$this->company(),'id'=>$id]);if(count($records)>50)throw HttpException::unprocessable('More than 50 evidence files. Export the originals individually.');$files=[];
            foreach($records as$row)if($row['purged_at']===null&&$this->checkedBytes($row)===false){$this->access($row,'integrity_failed');return ['integrity_failed'=>true];}
            foreach($records as$row){$file=$row;unset($file['company_id']);if($row['purged_at']!==null){unset($file['file_base64']);$file['file_status']='REMOVED_BY_RETENTION';}else{$this->access($row,'pack_exported');$file['file_status']='INCLUDED';}$file['access_history']=$this->history((string)$row['evidence_id']);$files[]=$file;}
            $this->audit->record('incident','investigation_pack_exported',$id);return ['format'=>'sentinel-investigation-pack-v1','generated_at'=>gmdate('Y-m-d H:i:s'),'incident'=>array_intersect_key($incident,array_flip(['incident_id','incident_number','site_id','severity','status','occurred_at','reported_at','description','actions_taken','resolution'])),'evidence'=>$files,'note'=>'Original byte hashes and application access receipts. This is not an independently timestamped, digitally signed or tamper-proof forensic certification. Existing mobile report photos are separate records and must be exported through their protected workflow.'];});
        if($result['integrity_failed']??false)throw HttpException::conflict('A stored original failed integrity verification. No pack was exported.');return $result;
    }
    public function policies(): array {return ['categories'=>array_map(static fn($category,$settings)=>['category'=>$category,'action'=>$settings[3]],array_keys(self::CATEGORIES),array_values(self::CATEGORIES)),'policies'=>$this->db->fetchAll('SELECT category,retention_days,updated_at,updated_by_user_id FROM retention_policies WHERE company_id=:company ORDER BY category',['company'=>$this->company()]),'holds'=>$this->db->fetchAll('SELECT * FROM retention_holds WHERE company_id=:company ORDER BY hold_id DESC LIMIT 500',['company'=>$this->company()]),'note'=>'No default deletion schedule. Cleanup is explicit, bounded to 500 records and requires a fresh preview. Location history and location-event payloads have separate policies; exports, mobile caches and backups require their own retention process.'];}
    public function policy(array $input): array {return $this->atomic(function()use($input){$this->mfa();$this->fields($input,['category','retention_days']);$category=$this->category($input['category']??null);$days=$this->number($input['retention_days']??null,7,3650);$keys=['company'=>$this->company(),'category'=>$category];$existing=$this->db->fetch('SELECT policy_id FROM retention_policies WHERE company_id=:company AND category=:category',$keys);if($existing)$this->db->execute('UPDATE retention_policies SET retention_days=:days,updated_by_user_id=:actor,updated_at=:now WHERE company_id=:company AND category=:category',$keys+['days'=>$days,'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);else $this->db->execute('INSERT INTO retention_policies(company_id,category,retention_days,updated_by_user_id,updated_at) VALUES(:company,:category,:days,:actor,:now)',$keys+['days'=>$days,'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);$this->audit->record('retention_policy','configured',null,[],[],['category'=>$category,'retention_days'=>$days]);return ['saved'=>true];});}
    public function hold(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['category','record_id','reason']);$category=$input['category']??null;if($category!=='incident')$category=$this->category($category);$record=empty($input['record_id'])?null:$this->number($input['record_id']);if($category==='incident'){if($record===null)throw HttpException::unprocessable('Choose an incident for an investigation hold.');$this->row('incidents','incident_id',$record);}elseif($record!==null){[$table,$key]=self::CATEGORIES[$category];$this->row($table,$key,$record);}
        $this->db->execute('INSERT INTO retention_holds(company_id,category,record_id,reason,created_by_user_id,created_at) VALUES(:company,:category,:record,:reason,:actor,:now)',['company'=>$this->company(),'category'=>$category,'record'=>$record,'reason'=>$this->text($input['reason']??null),'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('retention_hold');
    });}
    public function releaseHold(string $id,array $input): array {return $this->atomic(function()use($id,$input){$this->mfa();$this->fields($input,['reason']);$this->row('retention_holds','hold_id',$id);$this->db->execute('UPDATE retention_holds SET released_at=:now,released_by_user_id=:actor,release_reason=:reason WHERE company_id=:company AND hold_id=:id AND released_at IS NULL',['now'=>gmdate('Y-m-d H:i:s'),'actor'=>$this->actor(),'reason'=>$this->text($input['reason']??null),'company'=>$this->company(),'id'=>$id]);$this->audit->record('retention_hold','released',$id);return ['released'=>true];});}
    private function candidates(string $category,string $cutoff): array {
        [$table,$key,$date]=self::CATEGORIES[$category];$extra='';
        if($category==='incident_evidence')$extra=" AND r.purged_at IS NULL AND NOT EXISTS(SELECT 1 FROM retention_holds i WHERE i.company_id=r.company_id AND i.category='incident' AND i.record_id=r.incident_id AND i.released_at IS NULL)";
        if($category==='report_photos')$extra=" AND NOT EXISTS(SELECT 1 FROM retention_holds i WHERE i.company_id=r.company_id AND i.category='incident' AND r.report_type='incident' AND i.record_id=r.report_id AND i.released_at IS NULL)";
        if($category==='visitor_profiles')$extra=" AND r.visitor_status<>'ARCHIVED' AND NOT EXISTS(SELECT 1 FROM visitor_visits v WHERE v.company_id=r.company_id AND v.visitor_id=r.visitor_id AND v.visit_status IN ('PRE_REGISTERED','AUTHORIZED','CHECKED_IN'))";
        $rows=$this->db->fetchAll("SELECT r.$key AS id FROM $table r WHERE r.company_id=:company AND r.$date<:cutoff AND NOT EXISTS(SELECT 1 FROM retention_holds h WHERE h.company_id=r.company_id AND h.category=:category AND h.released_at IS NULL AND (h.record_id IS NULL OR h.record_id=r.$key))$extra ORDER BY r.$key LIMIT 500",['company'=>$this->company(),'cutoff'=>$cutoff,'category'=>$category]);return array_map(static fn($r)=>(int)$r['id'],$rows);
    }
    public function preview(array $input): array {return $this->atomic(function()use($input){
        $this->mfa();$this->fields($input,['category']);$category=$this->category($input['category']??null);$policy=$this->db->fetch('SELECT retention_days FROM retention_policies WHERE company_id=:company AND category=:category',['company'=>$this->company(),'category'=>$category])??throw HttpException::unprocessable('Configure a retention policy first.');$cutoff=gmdate('Y-m-d H:i:s',time()-(int)$policy['retention_days']*86400);$ids=$this->candidates($category,$cutoff);$token=bin2hex(random_bytes(32));$this->db->execute('INSERT INTO retention_previews(company_id,actor_user_id,token_hash,category,cutoff_at,policy_days,candidate_ids,expires_at) VALUES(:company,:actor,:hash,:category,:cutoff,:days,:ids,:expires)',['company'=>$this->company(),'actor'=>$this->actor(),'hash'=>hash('sha256',$token),'category'=>$category,'cutoff'=>$cutoff,'days'=>$policy['retention_days'],'ids'=>json_encode($ids,JSON_THROW_ON_ERROR),'expires'=>gmdate('Y-m-d H:i:s',time()+900)]);$this->audit->record('retention','previewed',null,[],[],['category'=>$category,'count'=>count($ids)]);return ['preview_code'=>$token,'category'=>$category,'action'=>self::CATEGORIES[$category][3],'cutoff_at'=>$cutoff,'candidate_ids'=>$ids,'count'=>count($ids),'batch_limit'=>500,'expires_in_minutes'=>15,'note'=>'Review these identifiers and holds. Execution rechecks policy and eligibility. Backups, downloaded copies and other tables are not changed.'];
    });}
    public function executeRetention(array $input): array {return $this->atomic(function()use($input){
        $this->mfa();$this->fields($input,['preview_code','confirmation']);if(($input['confirmation']??null)!=='DELETE EXPIRED DATA')throw HttpException::unprocessable('Type DELETE EXPIRED DATA to execute the reviewed batch.');$code=$this->text($input['preview_code']??null,64);$preview=$this->db->fetch('SELECT * FROM retention_previews WHERE company_id=:company AND actor_user_id=:actor AND token_hash=:hash',['company'=>$this->company(),'actor'=>$this->actor(),'hash'=>hash('sha256',$code)])??throw HttpException::notFound('Preview not found.');if($preview['consumed_at']!==null||$preview['expires_at']<=gmdate('Y-m-d H:i:s'))throw HttpException::conflict('Preview expired or was already used.');
        $category=$this->category($preview['category']);$policy=$this->db->fetch('SELECT retention_days FROM retention_policies WHERE company_id=:company AND category=:category',['company'=>$this->company(),'category'=>$category]);$ids=$this->candidates($category,$preview['cutoff_at']);if(!$policy||(int)$policy['retention_days']!==(int)$preview['policy_days']||json_encode($ids,JSON_THROW_ON_ERROR)!==$preview['candidate_ids'])throw HttpException::conflict('Policy, holds or eligible records changed. Generate and review a new preview.');
        [$table,$key,, $action]=self::CATEGORIES[$category];foreach($ids as$id){$params=['company'=>$this->company(),'id'=>$id];if($action==='REMOVE_FILE'){$e=$this->row('incident_evidence','evidence_id',$id);$this->access($e,'retention_removed');$this->db->execute("UPDATE incident_evidence SET file_base64='',original_filename='[removed]',description='[removed by retention]',purged_at=:now WHERE company_id=:company AND evidence_id=:id",$params+['now'=>gmdate('Y-m-d H:i:s')]);}elseif($action==='REDACT_PROFILE')$this->db->execute("UPDATE visitors SET first_name='REDACTED',last_name='REDACTED',contact_phone=NULL,contact_email=NULL,external_reference=NULL,visitor_status='ARCHIVED' WHERE company_id=:company AND visitor_id=:id",$params);else $this->db->execute("DELETE FROM $table WHERE company_id=:company AND $key=:id",$params);}
        $this->db->execute('UPDATE retention_previews SET consumed_at=:now WHERE company_id=:company AND preview_id=:id',['now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$preview['preview_id']]);$this->audit->record('retention','batch_completed',(string)$preview['preview_id'],[],[],['category'=>$category,'action'=>$action,'count'=>count($ids)]);return ['completed'=>true,'category'=>$category,'action'=>$action,'count'=>count($ids)];
    });}
}
